//! Print Clap-derived Markdown reference for `jj-gh` to stdout. The docs
//! build generates this into the mdBook source at build time,
//! so there is no generated Markdown file to commit.

use jj_gh::Cli;

const DOCS_BANNER: &str =
    "<!-- Generated by tools/gen-docs. Do not edit by hand. Run `nix build .#docs`. -->\n\n";

fn main() {
    print!("{DOCS_BANNER}{}", clap_markdown::help_markdown::<Cli>());
}
